-- Built-in content of the eight modes (283 elements), converted from the PostgreSQL seed.
-- `data` and `original` start identical; the Admin panel's Reset / Restore puts `original` back.

CREATE TABLE `_content_seed` (
    `mode` VARCHAR(191) NOT NULL,
    `itemId` VARCHAR(191) NOT NULL,
    `position` INTEGER NOT NULL,
    `data` JSON NOT NULL
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;


SELECT UUID(), `mode`, `itemId`, `position`, `data`, `data`, true, false, false, CURRENT_TIMESTAMP(3) FROM `_content_seed`;

DROP TABLE `_content_seed`;
